import Ajv from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

// Path and constraint, never data: ajv names versions differ on the path field, so both are read structurally.
interface SchemaError {
  instancePath?: string;
  dataPath?: string;
  message?: string;
}

// strict:false and no coercion, defaults or formats: validation enforces required, declared types and enum only.
const ajvOptions = {strict: false, validateFormats: false, allErrors: true};
const validator = new Ajv(ajvOptions);

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validators = new WeakMap<object, ReturnType<Ajv['compile']>>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    this.compiledValidator(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(...)...
  getDefinitions()...
  getPromptInstructions()...
  getExamplePrompts()...
  has(...)...

  /** Rejects input the schema rejects with a ToolResponse; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name, input, context): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.compiledValidator(definition.name, definition.inputSchema);
    if (!validate(input)) {
      const rejection = rejectionFor(definition, validate.errors ?? []);
      log.warn('tool', 'input rejected by schema', {name, reason: rejection});
      return {result: rejection};
    }
    ...rest unchanged...
  }

  private compiledValidator(toolName: string, schema: object): ReturnType<Ajv['compile']> {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    try {
      const compiled = validator.compile(schema);
      this.validators.set(schema, compiled);
      return compiled;
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`tool '${toolName}' has an invalid inputSchema: ${reason}`);
    }
  }
}

function rejectionFor(definition: ToolDefinition, errors: SchemaError[]): string {
  return `invalid input for tool '${definition.name}': ${errors.map(describeError).join('; ')}`;
}

function describeError(error: SchemaError): string {
  const rawPath = error.instancePath ?? error.dataPath ?? '';
  return `${toFieldPath(rawPath)} ${error.message ?? 'failed validation'}`;
}

function toFieldPath(rawPath: string): string {
  const segments = rawPath.split('/');
  const dotted = segments.join('.');
  if (dotted === '') return 'input';
  return dotted.slice(1);
}
```

