import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('rejects input missing a required property before the executor runs', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      namesLocation: response.result.includes('location'),
      namesRequired: /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesLocation: true,
      namesRequired: true,
    });
  });
});

